'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const C = input[2];
const A = input.slice(3);

let total = 0;
for (const x of A) total += x;

let minCovered = 0;

if (C === 1) {
  A.sort((a, b) => a - b);
  for (let i = 0; i < K; i++) minCovered += A[i];
} else {
  const windowSums = new Float64Array(N - C + 1);
  let sum = 0;

  for (let i = 0; i < C; i++) sum += A[i];
  windowSums[0] = sum;

  for (let start = 1; start <= N - C; start++) {
    sum += A[start + C - 1] - A[start - 1];
    windowSums[start] = sum;
  }

  let prev = new Float64Array(N + 1);
  let curr = new Float64Array(N + 1);
  prev.fill(0);

  for (let j = 1; j <= K; j++) {
    const first = j * C;
    curr[first - 1] = Infinity;

    for (let i = first; i <= N; i++) {
      const skip = curr[i - 1];
      const place = prev[i - C] + windowSums[i - C];
      curr[i] = Math.min(skip, place);
    }

    [prev, curr] = [curr, prev];
  }

  minCovered = prev[N];
}

console.log(total - minCovered);
